import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { compileThemeWithModes } from "@sentropic/design-system-themes";
import { devmtlTheme } from "../dist/index.js";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

export function buildDevmtlCss(theme = devmtlTheme) {
  return [
    "/* Generated by packages/theme-devmtl/scripts/build-css.mjs via compileThemeWithModes. */",
    `/* Theme: ${theme.label} (${theme.id}) */`,
    `/* Dark mode: ${theme.tokensDark ? "3 blocks (light + auto + explicit)" : "none (light v0)"} */`,
    compileThemeWithModes(theme, {
      selector: ':root, [data-theme="devmtl"], [data-st-theme="devmtl"]'
    })
  ].join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const content = buildDevmtlCss(devmtlTheme);
  if (process.argv.includes("--stdout")) {
    process.stdout.write(content);
  } else {
    const cssDir = join(root, "css");
    mkdirSync(cssDir, { recursive: true });
    writeFileSync(join(cssDir, `${devmtlTheme.id}.css`), content);
  }
}
